import { useCallback, useEffect, useRef, useState, type FormEvent } from "react";
import { downloadFile } from "./graph-export.ts";
import { parseWorkspacePayload, type WorkspacePayload } from "./workspace.ts";
import { latestBinding, syncDialogElement } from "./workspace-library.ts";
import {
  encodeWorkspaceSnapshot,
  prepareWorkspaceSnapshotPayload,
  readWorkspaceSnapshotFile,
  snapshotFilename,
  type WorkspaceSnapshotSource,
} from "./workspace-snapshots.ts";
import {
  createWorkspaceSnapshot,
  deleteWorkspaceSnapshot,
  listWorkspaceSnapshots,
  readWorkspaceSnapshot,
  renameWorkspaceSnapshot,
  updateWorkspaceSnapshot,
  WorkspaceSnapshotConflictError,
  type WorkspaceSnapshotMetadata,
  type WorkspaceSnapshotRecord,
} from "./workspace-snapshot-store.ts";
import "./workspace-dialogs.css";

type Options = {
  /** Null when this page's identity cannot name a library: every action is then unavailable. */
  source: WorkspaceSnapshotSource | null;
  capture: () => WorkspacePayload;
  replace: (payload: WorkspacePayload) => void;
  hasContent: () => boolean;
  busy: boolean;
  ready: boolean;
  notify: (message: string) => void;
  /** The visible toolbar trigger, including browsers that do not focus a clicked menu item. */
  returnFocusTarget?: () => HTMLElement | null;
};

type OpenGraph = {
  payload: WorkspacePayload;
  name: string;
  active: WorkspaceSnapshotMetadata | null;
  warning: "foreign" | "unknown" | null;
};

type SaveGraph = {
  kind: "save";
  payload: WorkspacePayload;
  raw: string;
  name: string;
  target: WorkspaceSnapshotMetadata | null;
  mode: "new" | "update";
  download: boolean;
  conflict: boolean;
  downloadOnly: boolean;
  after?: OpenGraph;
};

type DialogState = SaveGraph | { kind: "library" } | { kind: "reading"; name: string }
  | { kind: "replace"; graph: OpenGraph; confirmed: boolean };

function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "This browser could not complete the operation. Try again.";
}

function metadata(record: WorkspaceSnapshotRecord): WorkspaceSnapshotMetadata {
  const { raw: _raw, ...result } = record;
  return result;
}

/** Named browser saves and portable files share one validated, immutable capture of the current view. */
export function useWorkspaceLibrary(options: Options) {
  const latest = useRef(options);
  latest.current = options;
  const sourceKey = JSON.stringify(options.source);
  const scope = useRef(sourceKey);
  const generation = useRef(0);
  // Invalidate during render too: a completed read must not run between a source change and its effect.
  const sourceChanged = scope.current !== sourceKey;
  if (sourceChanged) {
    scope.current = sourceKey;
    generation.current++;
  }
  const mounted = useRef(true);
  const operation = useRef(0);
  const committing = useRef(false);
  const [active, updateActive] = useState<WorkspaceSnapshotMetadata | null>(null);
  const activeRef = useRef(active);
  /** What this page last saved or renamed for each saved graph, null for one it deleted (see latestBinding). */
  const known = useRef(new Map<string, WorkspaceSnapshotMetadata | null>());
  if (sourceChanged) {
    activeRef.current = null;
    known.current = new Map();
  }
  const setActive = useCallback((saved: WorkspaceSnapshotMetadata | null) => {
    activeRef.current = saved;
    updateActive(saved);
  }, []);
  const getActive = useCallback(() => activeRef.current, []);
  /** Puts back a binding Undo or Redo kept, as this page's later saves, renames and deletes left that saved graph. */
  const restoreActive = useCallback((binding: WorkspaceSnapshotMetadata | null) =>
    setActive(latestBinding(known.current, binding)), [setActive]);
  const remember = (saved: WorkspaceSnapshotMetadata) => {
    known.current.set(saved.id, saved);
    return saved;
  };
  const [dialog, setDialog] = useState<DialogState | null>(null);
  const dialogRef = useRef(dialog);
  dialogRef.current = dialog;
  const [error, setError] = useState<string | null>(null);
  const [working, setWorking] = useState(false);
  const [items, setItems] = useState<WorkspaceSnapshotMetadata[]>([]);
  const [rename, setRename] = useState<{ item: WorkspaceSnapshotMetadata; name: string } | null>(null);
  const [deleting, setDeleting] = useState<WorkspaceSnapshotMetadata | null>(null);
  const nativeDialog = useRef<HTMLDialogElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const origin = useRef<HTMLElement | null>(null);

  const rememberOrigin = () => {
    const element = document.activeElement;
    if (element instanceof HTMLElement && nativeDialog.current?.contains(element)) return;
    origin.current = latest.current.returnFocusTarget?.() ?? (element instanceof HTMLElement ? element : null);
  };

  const returnFocus = () => {
    const element = origin.current;
    const menu = element?.closest("details");
    const remembered = menu && !menu.open ? menu.querySelector("summary") : element;
    const target = remembered?.isConnected ? remembered : latest.current.returnFocusTarget?.();
    if (target instanceof HTMLElement && target.isConnected) target.focus();
  };

  const beginOperation = (commit = false) => {
    const id = ++operation.current;
    const version = generation.current;
    committing.current = commit;
    setWorking(true);
    setError(null);
    return () => mounted.current && generation.current === version && operation.current === id;
  };

  const finishOperation = (valid: () => boolean) => {
    if (!valid()) return;
    committing.current = false;
    setWorking(false);
  };

  const dismiss = useCallback(() => {
    if (committing.current) return;
    operation.current++;
    setWorking(false);
    setError(null);
    setRename(null);
    setDeleting(null);
    setDialog(null);
  }, []);

  useEffect(() => {
    operation.current++;
    committing.current = false;
    setWorking(false);
    setActive(null);
    setDialog(null);
    setError(null);
    setItems([]);
    setRename(null);
    setDeleting(null);
  }, [sourceKey]);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      generation.current++;
    };
  }, []);

  const shownKind = useRef<DialogState["kind"] | null>(null);
  useEffect(() => {
    const element = nativeDialog.current;
    if (!element) return;
    const change = syncDialogElement(element, dialog !== null);
    // Focus moves in only when a dialog appears or turns into another one, not while its fields are edited.
    if (dialog && (change === "opened" || shownKind.current !== dialog.kind)) {
      element.querySelector<HTMLElement>("[data-workspace-autofocus]")?.focus();
    }
    if (change === "closed") returnFocus();
    shownKind.current = dialog?.kind ?? null;
  }, [dialog]);

  const refresh = async () => {
    const source = latest.current.source;
    if (!latest.current.ready || !source || committing.current) return;
    const valid = beginOperation();
    try {
      const saved = await listWorkspaceSnapshots(source);
      if (valid()) setItems(saved);
    } catch (failure) {
      if (valid()) setError(errorMessage(failure));
    } finally {
      finishOperation(valid);
    }
  };

  const refreshAfterError = async (failure: unknown, source: WorkspaceSnapshotSource, valid: () => boolean) => {
    if (!valid()) return;
    committing.current = false;
    const message = errorMessage(failure);
    setError(message);
    if (failure instanceof WorkspaceSnapshotConflictError) {
      setRename(null);
      setDeleting(null);
    }
    try {
      const saved = await listWorkspaceSnapshots(source);
      if (valid()) setItems(saved);
    } catch (refreshFailure) {
      if (valid()) setError(`${message} The library could not be refreshed: ${errorMessage(refreshFailure)}`);
    }
  };

  const apply = (graph: OpenGraph) => {
    if (!latest.current.ready || !latest.current.source) return;
    latest.current.replace(graph.payload);
    setActive(graph.active);
    setDialog(null);
    setError(null);
    latest.current.notify(`Opened “${graph.name}”. Undo brings back the previous graph.`);
  };

  const requestOpen = (graph: OpenGraph) => {
    if (!latest.current.ready || !latest.current.source) return;
    if (latest.current.hasContent() || graph.warning) {
      setError(null);
      setDialog({ kind: "replace", graph, confirmed: !graph.warning });
    } else {
      apply(graph);
    }
  };

  const beginSave = (download = false, after?: OpenGraph) => {
    const source = latest.current.source;
    if (!latest.current.ready || !source || latest.current.busy || committing.current) return;
    if (!after) rememberOrigin();
    setError(null);
    try {
      // The payload read back from the strict prepared text is detached from the page's mutable graph objects.
      const { raw, payload } = prepareWorkspaceSnapshotPayload({ ...latest.current.capture(), savedAt: new Date().toISOString() });
      const target = activeRef.current;
      setDialog({ kind: "save", payload, raw, name: target?.name ?? `Graph — ${source.repositoryId}`, target,
        mode: target ? "update" : "new", download, conflict: false, downloadOnly: false, after });
    } catch (failure) {
      const message = errorMessage(failure);
      if (dialogRef.current) setError(message);
      else latest.current.notify(message);
    }
  };

  const save = (download = false) => beginSave(download);

  const open = () => {
    if (!latest.current.ready || !latest.current.source || committing.current) return;
    rememberOrigin();
    setRename(null);
    setDeleting(null);
    setDialog({ kind: "library" });
    void refresh();
  };

  const load = () => {
    if (!latest.current.ready || !latest.current.source || committing.current) return;
    if (!dialogRef.current) rememberOrigin();
    if (fileInput.current) {
      fileInput.current.value = "";
      fileInput.current.click();
    }
  };

  const readFile = async (file: File) => {
    const source = latest.current.source;
    if (!latest.current.ready || !source || committing.current) return;
    setDialog({ kind: "reading", name: file.name });
    const valid = beginOperation();
    try {
      const imported = await readWorkspaceSnapshotFile(file, source);
      if (!valid()) return;
      requestOpen({ payload: imported.payload, name: imported.name || file.name, active: null,
        warning: imported.sameSource ? null : imported.source ? "foreign" : "unknown" });
    } catch (failure) {
      if (valid()) setError(errorMessage(failure));
    } finally {
      finishOperation(valid);
    }
  };

  const readSaved = async (item: WorkspaceSnapshotMetadata) => {
    const source = latest.current.source;
    if (!latest.current.ready || !source || committing.current) return;
    const valid = beginOperation();
    try {
      const record = await readWorkspaceSnapshot(source, item.id);
      if (!record) throw new Error("This saved graph was deleted in another tab. Refresh the list to continue.");
      const payload = parseWorkspacePayload(record.raw, { repositoryReferences: true });
      if (!payload) throw new Error("This saved graph is invalid and cannot be opened.");
      if (valid()) requestOpen({ payload, name: record.name, active: metadata(record), warning: null });
    } catch (failure) {
      if (dialogRef.current?.kind === "library") await refreshAfterError(failure, source, valid);
      else if (valid()) setError(errorMessage(failure));
    } finally {
      finishOperation(valid);
    }
  };

  const downloadCapture = (name: string, document: string) => {
    downloadFile(new Blob([document], { type: "application/json" }), snapshotFilename(name));
  };

  const submitSave = async (event: FormEvent) => {
    event.preventDefault();
    const session = dialogRef.current;
    const source = latest.current.source;
    if (session?.kind !== "save" || !latest.current.ready || !source || latest.current.busy || committing.current) return;
    const name = session.name.trim();
    if (!name) {
      setError("Enter a graph name.");
      return;
    }
    let document: string | null = null;
    try {
      // Validate the download before committing: both destinations use the same capture and timestamp.
      if (session.download) document = encodeWorkspaceSnapshot(name, source, session.payload);
    } catch (failure) {
      setError(errorMessage(failure));
      return;
    }
    const valid = beginOperation(true);
    // The dialog's payload was read back from `raw` when it was prepared: the store need not read it again.
    const counts = { nodeCount: session.payload.graph.nodes.length, edgeCount: session.payload.graph.edges.length };
    let stored: WorkspaceSnapshotRecord;
    try {
      stored = session.mode === "update" && session.target
        ? await updateWorkspaceSnapshot(source, session.target.id, session.target.revision, session.raw, name, counts)
        : await createWorkspaceSnapshot(source, name, session.raw, counts);
    } catch (failure) {
      if (valid()) {
        setError(errorMessage(failure));
        setDialog({ ...session, conflict: failure instanceof WorkspaceSnapshotConflictError, downloadOnly: session.download });
      }
      finishOperation(valid);
      return;
    }
    if (!valid()) return;
    setActive(remember(metadata(stored)));
    latest.current.notify(`Saved “${stored.name}” in this browser.`);
    if (document !== null) {
      try {
        downloadCapture(name, document);
        latest.current.notify(`Saved “${stored.name}” in this browser. Download initiated; check your browser's downloads.`);
      } catch (failure) {
        setError(`Saved in this browser, but the download could not start: ${errorMessage(failure)}`);
        setDialog({ ...session, target: metadata(stored), mode: "update", downloadOnly: true });
        finishOperation(valid);
        return;
      }
    }
    finishOperation(valid);
    if (session.after) apply(session.after);
    else setDialog(null);
  };

  const downloadOnly = () => {
    const session = dialogRef.current;
    const source = latest.current.source;
    if (session?.kind !== "save" || !latest.current.ready || !source || working) return;
    try {
      const name = session.name.trim();
      if (!name) throw new Error("Enter a graph name.");
      const document = encodeWorkspaceSnapshot(name, source, session.payload);
      downloadCapture(name, document);
      latest.current.notify(`Download initiated for “${name}”; check your browser's downloads.`);
      // Downloading alone cannot satisfy Save current before replacing a graph.
      setDialog(null);
    } catch (failure) {
      setError(errorMessage(failure));
    }
  };

  const submitRename = async (event: FormEvent) => {
    event.preventDefault();
    const source = latest.current.source;
    if (!rename || !latest.current.ready || !source || working || committing.current) return;
    const name = rename.name.trim();
    if (!name) {
      setError("Enter a graph name.");
      return;
    }
    const valid = beginOperation(true);
    try {
      const renamed = await renameWorkspaceSnapshot(source, rename.item.id, rename.item.revision, name);
      if (!valid()) return;
      const updated = remember(metadata(renamed));
      setItems(current => current.map(item => item.id === updated.id ? updated : item)
        .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
      setRename(null);
      if (activeRef.current?.id === renamed.id) setActive(updated);
      const saved = await listWorkspaceSnapshots(source);
      if (valid()) setItems(saved);
    } catch (failure) {
      await refreshAfterError(failure, source, valid);
    } finally {
      finishOperation(valid);
    }
  };

  const remove = async () => {
    const source = latest.current.source;
    if (!deleting || !latest.current.ready || !source || working || committing.current) return;
    const valid = beginOperation(true);
    try {
      await deleteWorkspaceSnapshot(source, deleting.id, deleting.revision);
      known.current.set(deleting.id, null);
      if (!valid()) return;
      setItems(current => current.filter(item => item.id !== deleting.id));
      setDeleting(null);
      if (activeRef.current?.id === deleting.id) setActive(null);
      const saved = await listWorkspaceSnapshots(source);
      if (valid()) setItems(saved);
    } catch (failure) {
      await refreshAfterError(failure, source, valid);
    } finally {
      finishOperation(valid);
    }
  };

  const secondaryClass = "workbench-action workbench-action--secondary";
  const ghostClass = "workbench-action workbench-action--ghost";
  const title = dialog?.kind === "save" ? "Save graph" : dialog?.kind === "library" ? "Open saved graph" : "Open graph";
  const saveSession = dialog?.kind === "save" ? dialog : null;

  const dialogs = <>
    <input ref={fileInput} type="file" className="workspace-library-file" tabIndex={-1} aria-hidden="true"
      accept=".json,.rdf4j-graph.json,application/json" onChange={event => {
        const file = event.currentTarget.files?.[0];
        if (file) void readFile(file);
      }} />
    <dialog ref={nativeDialog} className="workspace-library-dialog" aria-label={title}
      aria-busy={working} onCancel={event => { event.preventDefault(); dismiss(); }}
      onClose={() => { if (!nativeDialog.current?.open && dialogRef.current && !committing.current) dismiss(); }}>
      <div className="workspace-library-heading">
        <h2>{title}</h2>
        <button type="button" className={ghostClass} aria-label={`Close ${title.toLowerCase()}`}
          disabled={committing.current} onClick={dismiss}>Close</button>
      </div>
      {error ? <p className="workspace-library-error" role="alert">{error}</p> : null}
      {saveSession ? <form onSubmit={event => void submitSave(event)} className="workspace-library-form">
        <label className="workspace-library-field">Graph name
          <input data-workspace-autofocus value={saveSession.name} maxLength={256} required disabled={working}
            onChange={event => setDialog({ ...saveSession, name: event.target.value })} />
        </label>
        {saveSession.target ? <fieldset className="workspace-library-options" disabled={working}>
          <legend>Save destination</legend>
          <label><input type="radio" name="workspace-save-mode" checked={saveSession.mode === "update"}
            onChange={() => setDialog({ ...saveSession, mode: "update", conflict: false })} />Update existing</label>
          <label><input type="radio" name="workspace-save-mode" checked={saveSession.mode === "new"}
            onChange={() => setDialog({ ...saveSession, mode: "new", conflict: false })} />Save as new</label>
        </fieldset> : null}
        <p className="workspace-library-note">Saves a named copy in this browser for this server and repository.
          {saveSession.download ? " A portable JSON download starts after the browser save succeeds." : ""}</p>
        {saveSession.conflict ? <div className="workspace-library-warning" role="note">
          <p>This saved graph changed in another tab. Reload its latest version or save this capture as a new graph.</p>
          <div className="workspace-library-actions">
            <button type="button" className={secondaryClass} disabled={working}
              onClick={() => { if (saveSession.target) void readSaved(saveSession.target); }}>Reload saved graph</button>
            <button type="button" className={secondaryClass} disabled={working}
              onClick={() => setDialog({ ...saveSession, mode: "new", conflict: false })}>Save as new</button>
          </div>
        </div> : null}
        <div className="workspace-library-actions">
          <button type="button" className={ghostClass} disabled={committing.current} onClick={dismiss}>Cancel</button>
          {saveSession.downloadOnly ? <button type="button" className={secondaryClass} disabled={working}
            onClick={downloadOnly}>Download only</button> : null}
          <button type="submit" className="workbench-action workbench-action--primary"
            disabled={working || options.busy || !options.ready || (saveSession.conflict && saveSession.mode === "update")}>
            {working ? "Saving…" : saveSession.download ? "Save and download" : "Save"}
          </button>
        </div>
      </form> : null}
      {dialog?.kind === "library" ? <div className="workspace-library-body">
        <p className="workspace-library-note">Named graphs saved in this browser for this server and repository.</p>
        <button type="button" className={ghostClass} disabled={working} onClick={() => void refresh()}>Refresh saved graphs</button>
        {working ? <p role="status">Loading saved graphs…</p> : null}
        {!working && !items.length ? <p>No saved graphs yet.</p> : null}
        <ul className="workspace-library-list">
          {items.map(item => <li key={item.id} className="workspace-library-item">
            <div className="workspace-library-item-description"><strong>{item.name}</strong>
              <small><time dateTime={item.updatedAt}>{new Date(item.updatedAt).toLocaleString()}</time>
                {` · ${item.nodeCount.toLocaleString()} nodes · ${item.edgeCount.toLocaleString()} edges`}</small>
            </div>
            <div className="workspace-library-actions">
              <button type="button" className={secondaryClass} disabled={working} onClick={() => void readSaved(item)}>Open</button>
              <button type="button" className={ghostClass} disabled={working}
                onClick={() => { setRename({ item, name: item.name }); setDeleting(null); setError(null); }}>Rename</button>
              <button type="button" className={ghostClass} disabled={working}
                onClick={() => { setDeleting(item); setRename(null); setError(null); }}>Delete</button>
            </div>
          </li>)}
        </ul>
        {rename ? <form className="workspace-library-inline" aria-label={`Rename ${rename.item.name}`} onSubmit={event => void submitRename(event)}>
          <label className="workspace-library-field">Graph name
            <input value={rename.name} required maxLength={256} disabled={working}
              onChange={event => setRename({ ...rename, name: event.target.value })} />
          </label>
          <div className="workspace-library-actions"><button type="submit" className={secondaryClass} disabled={working}>Rename graph</button>
            <button type="button" className={ghostClass} disabled={working} onClick={() => setRename(null)}>Cancel rename</button></div>
        </form> : null}
        {deleting ? <section className="workspace-library-warning" aria-label={`Delete ${deleting.name}`}>
          <p>Delete “{deleting.name}” from this browser? The graph currently shown stays unchanged.</p>
          <div className="workspace-library-actions"><button type="button" className={secondaryClass} disabled={working} onClick={() => void remove()}>Delete saved graph</button>
            <button type="button" className={ghostClass} disabled={working} onClick={() => setDeleting(null)}>Cancel delete</button></div>
        </section> : null}
      </div> : null}
      {dialog?.kind === "reading" ? <div className="workspace-library-body">
        <p role="status">{working ? `Reading and validating “${dialog.name}”…` : `“${dialog.name}” could not be opened.`}</p>
        <div className="workspace-library-actions"><button type="button" className={ghostClass} onClick={dismiss}>Cancel</button>
          {!working ? <button type="button" className={secondaryClass} onClick={load}>Choose another file</button> : null}</div>
      </div> : null}
      {dialog?.kind === "replace" ? <div className="workspace-library-body">
        <p>Open “{dialog.graph.name}”? The current view will be replaced. Undo brings it back.</p>
        {dialog.graph.warning ? <div className="workspace-library-warning">
          <p>{dialog.graph.warning === "foreign"
            ? "This graph comes from a different server or repository. Repository references may identify different data here."
            : "This file does not identify its server and repository. Repository references may identify different data here."}</p>
          <label><input type="checkbox" checked={dialog.confirmed}
            onChange={event => setDialog({ ...dialog, confirmed: event.target.checked })} />
            I understand and want to open this graph here.</label>
        </div> : null}
        <div className="workspace-library-actions">
          <button type="button" className={ghostClass} data-workspace-autofocus onClick={dismiss}>Cancel</button>
          <button type="button" className={secondaryClass} disabled={!dialog.confirmed || options.busy || !options.ready}
            onClick={() => beginSave(false, dialog.graph)}>Save current</button>
          <button type="button" className="workbench-action workbench-action--primary" disabled={!dialog.confirmed || !options.ready}
            onClick={() => apply(dialog.graph)}>Open without saving</button>
        </div>
      </div> : null}
    </dialog>
  </>;

  const available = options.ready && options.source !== null;
  return { active, available, setActive, getActive, restoreActive, save, open, load, dialogs };
}
